import{_ as o,o as i,c as l,ag as t}from"./chunks/framework.BIYp5CeQ.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":null}'),a={name:"guide/troubleshooting.md"};function s(r,e,n,d,c,h){return i(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>This page covers common issues encountered while integrating or publishing SweetEditor.</p><h2 id="github-pages-shows-plain-markdown-instead-of-the-vitepress-site" tabindex="-1">GitHub Pages Shows Plain Markdown Instead Of The VitePress Site <a class="header-anchor" href="#github-pages-shows-plain-markdown-instead-of-the-vitepress-site" aria-label="Permalink to &quot;GitHub Pages Shows Plain Markdown Instead Of The VitePress Site&quot;">​</a></h2><p>Cause:</p><ul><li>GitHub Pages is still deploying the branch or <code>docs/</code> folder directly instead of the GitHub Actions build artifact</li></ul><p>Fix:</p><ol><li>Open repository <code>Settings</code></li><li>Go to <code>Pages</code></li><li>Set <code>Build and deployment &gt; Source</code> to <code>GitHub Actions</code></li><li>Re-run the Pages workflow</li></ol><h2 id="homepage-hero-image-or-logo-does-not-show" tabindex="-1">Homepage Hero Image Or Logo Does Not Show <a class="header-anchor" href="#homepage-hero-image-or-logo-does-not-show" aria-label="Permalink to &quot;Homepage Hero Image Or Logo Does Not Show&quot;">​</a></h2><p>Cause:</p><ul><li>VitePress homepage and logo use static public assets</li><li>the image must exist under <code>docs/public</code></li></ul><p>Fix:</p><ul><li>keep hero/logo images under <code>docs/public/...</code></li><li>use public paths such as <code>/snapshot/Screenshot_Desktop.png</code></li></ul><h2 id="decorations-keep-duplicating-while-scrolling" tabindex="-1">Decorations Keep Duplicating While Scrolling <a class="header-anchor" href="#decorations-keep-duplicating-while-scrolling" aria-label="Permalink to &quot;Decorations Keep Duplicating While Scrolling&quot;">​</a></h2><p>Cause:</p><ul><li>a viewport-scoped decoration provider uses <code>DecorationApplyMode.Merge</code></li></ul><p>Fix:</p><ul><li>use <code>DecorationApplyMode.ReplaceRange</code> for line-based viewport recomputation</li></ul><h2 id="completion-does-not-appear" tabindex="-1">Completion Does Not Appear <a class="header-anchor" href="#completion-does-not-appear" aria-label="Permalink to &quot;Completion Does Not Appear&quot;">​</a></h2><p>Checklist:</p><ul><li>a <code>CompletionProvider</code> is registered with <code>addCompletionProvider()</code></li><li>completion is manually triggered or a trigger character is supported</li><li>the controller is not currently in a conflicting state such as linked editing</li></ul><h2 id="inline-suggestion-does-not-show" tabindex="-1">Inline Suggestion Does Not Show <a class="header-anchor" href="#inline-suggestion-does-not-show" aria-label="Permalink to &quot;Inline Suggestion Does Not Show&quot;">​</a></h2><p>Checklist:</p><ul><li>call <code>controller.inlineSuggestions().show(...)</code></li><li>use a valid 0-based <code>line</code> and <code>column</code></li><li>ensure the document is loaded before showing the suggestion</li></ul><h2 id="theme-changes-do-not-apply" tabindex="-1">Theme Changes Do Not Apply <a class="header-anchor" href="#theme-changes-do-not-apply" aria-label="Permalink to &quot;Theme Changes Do Not Apply&quot;">​</a></h2><p>Checklist:</p><ul><li>call <code>controller.applyTheme(theme)</code></li><li>use <code>rememberEditorAppearance()</code> or <code>rememberEditorTheme()</code> consistently</li><li>keep behavior changes in <code>EditorSettings</code>, not in theme content</li></ul><h2 id="desktop-mouse-wheel-feels-wrong" tabindex="-1">Desktop Mouse Wheel Feels Wrong <a class="header-anchor" href="#desktop-mouse-wheel-feels-wrong" aria-label="Permalink to &quot;Desktop Mouse Wheel Feels Wrong&quot;">​</a></h2><p>Note:</p><ul><li>Desktop wheel normalization is handled at the platform layer</li><li>verify the latest editor-compose version and site build if behavior differs between local and published versions</li></ul><h2 id="build-succeeds-locally-but-site-looks-old-online" tabindex="-1">Build Succeeds Locally But Site Looks Old Online <a class="header-anchor" href="#build-succeeds-locally-but-site-looks-old-online" aria-label="Permalink to &quot;Build Succeeds Locally But Site Looks Old Online&quot;">​</a></h2><p>Cause:</p><ul><li>Pages may still be serving an old deployment or the wrong deployment source</li></ul><p>Fix:</p><ul><li>verify latest workflow run succeeded</li><li>verify Pages source is <code>GitHub Actions</code></li><li>refresh after deployment completes</li></ul><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./architecture">Architecture</a></li><li><a href="./theme-appearance">Theme / Appearance</a></li><li><a href="./api-cookbook">API Cookbook</a></li><li><a href="./faq">FAQ</a></li></ul>',36)])])}const g=o(a,[["render",s]]);export{p as __pageData,g as default};
